module knapsack_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [3:0] k,\n    input [8:0] s_0, s_1, s_2, s_3, s_4, s_5, s_6, s_7,\n    input [31:0] v_0, v_1, v_2, v_3, v_4, v_5, v_6, v_7,\n    output [31:0] result_1, result_2, result_3, result_4, result_5, result_6, result_7, result_8, result_9, result_10, result_11, result_12, result_13, result_14, result_15, result_16,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE       = 2'd0;\n    localparam [1:0] INIT       = 2'd1;\n    localparam [1:0] RUN_JEWEL  = 2'd2;\n    localparam [1:0] RUN_CAP    = 2'd3;\n    localparam [1:0] FINISH     = 2'd4;\n    \n    reg [1:0] state, next_state;\n    reg [2:0] jewel_idx;\n    reg [3:0] capacity;\n    reg [3:0] k_reg;\n    reg [2:0] n_reg;\n    reg [8:0] s_reg [0:7];\n    reg [31:0] v_reg [0:7];\n    reg [31:0] dp [0:16]; // dp[0] unused but kept for indexing\n    reg [31:0] new_value;\n    reg [8:0] current_s;\n    reg [31:0] current_v;\n    reg [7:0] cycle_count;\n\n    integer i;\n\n    // Output assignments\n    assign result_1  = dp[1];\n    assign result_2  = dp[2];\n    assign result_3  = dp[3];\n    assign result_4  = dp[4];\n    assign result_5  = dp[5];\n    assign result_6  = dp[6];\n    assign result_7  = dp[7];\n    assign result_8  = dp[8];\n    assign result_9  = dp[9];\n    assign result_10 = dp[10];\n    assign result_11 = dp[11];\n    assign result_12 = dp[12];\n    assign result_13 = dp[13];\n    assign result_14 = dp[14];\n    assign result_15 = dp[15];\n    assign result_16 = dp[16];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            jewel_idx <= 3'd0;\n            cycle_count <= 8'd0;\n\n            // Initialize dp array\n            for (i = 0; i <= 16; i = i + 1) begin\n                dp[i] <= 32'd0;\n            end\n            \n            // Initialize stored arrays\n            for (i = 0; i < 8; i = i + 1) begin\n                s_reg[i] <= 9'd0;\n                v_reg[i] <= 32'd0;\n            end\n        end else begin\n            state <= next_state;\n            cycle_count <= cycle_count + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    jewel_idx <= 3'd0;\n                    cycle_count <= 8'd0;\n                    if (start) next_state <= INIT;\n                    else next_state <= IDLE;\n                end\n                \n                INIT: begin\n                    k_reg <= k;\n                    n_reg <= n;\n                    s_reg[0] <= s_0;\n                    s_reg[1] <= s_1;\n                    s_reg[2] <= s_2;\n                    s_reg[3] <= s_3;\n                    s_reg[4] <= s_4;\n                    s_reg[5] <= s_5;\n                    s_reg[6] <= s_6;\n                    s_reg[7] <= s_7;\n                    \n                    v_reg[0] <= v_0;\n                    v_reg[1] <= v_1;\n                    v_reg[2] <= v_2;\n                    v_reg[3] <= v_3;\n                    v_reg[4] <= v_4;\n                    v_reg[5] <= v_5;\n                    v_reg[6] <= v_6;\n                    v_reg[7] <= v_7;\n                    \n                    // Initialize dp array\n                    for (i = 1; i <= 16; i = i + 1) begin\n                        dp[i] <= 32'd0;\n                    end\n                    next_state <= RUN_JEWEL;\n                end\n                \n                RUN_JEWEL: begin\n                    if (cycle_count >= 8'd128) begin\n                        next_state <= FINISH;\n                    end else if (jewel_idx < n_reg) begin\n                        current_s <= s_reg[jewel_idx];\n                        current_v <= v_reg[jewel_idx];\n                        if (current_s <= {5'b0, k_reg}) begin\n                            capacity <= k_reg;\n                            next_state <= RUN_CAP;\n                        end else begin\n                            jewel_idx <= jewel_idx + 3'd1;\n                            next_state <= RUN_JEWEL;\n                        end\n                    end else begin\n                        next_state <= FINISH;\n                    end\n                end\n                \n                RUN_CAP: begin\n                    if (capacity >= current_s) begin\n                        new_value = dp[capacity - current_s] + current_v;\n                        if (new_value > dp[capacity]) begin\n                            dp[capacity] <= new_value;\n                        end\n                        capacity <= capacity - 4'd1;\n                        next_state <= RUN_CAP;\n                    end else begin\n                        jewel_idx <= jewel_idx + 3'd1;\n                        next_state <= RUN_JEWEL;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule